import{z as o,x as A,o as n,c as d,q as B,j as l,D as e,d as r,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"5NF 与反规范化","description":"","frontmatter":{"title":"5NF 与反规范化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/5nf-denormalization.md","filePath":"cs/5nf-denormalization.md","lastUpdated":1791413859000}'),p={name:"cs/5nf-denormalization.md"};function F(D,a,m,N,f,h){const t=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=B('<h1 id="_5nf-与反规范化" tabindex="-1">5NF 与反规范化 <a class="header-anchor" href="#_5nf-与反规范化" aria-label="Permalink to &quot;5NF 与反规范化&quot;">​</a></h1><div class="epigraph"><p>5NF 要求凡是无损的 n 路投影分解，其连接依赖都由候选键蕴含。反规范化则故意留下冗余，用完整性预算换少连接。</p><footer>—— 据 Fagin, Normal Forms and Relational Database Operators, SIGMOD 1979；Date；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/mvd-4nf">上一课</a>沿独立多值拆表。本课不重定义 MVD。缺口有两向：更细的连接依赖（JD）与 5NF；以及工程上反向走的反规范化。依赖理论单元在此封口，优化器单元从 Selinger 再开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有的关系 4NF 已过，仍存在：它等于三个投影的连接，但任两路连接都不够——必须三路才无损。这是连接依赖 \\(* (X,Y,Z)\\)。5NF（投影-连接范式，PJ/NF）：每个 JD 都被候选键所蕴含（分解平凡）。实践中真正常见的是供应商–零件–项目一类约束，比 4NF 稀。</p><p>反规范化：故意保留违反 3NF/BCNF 的列（如订单行上重复顾客名），减少查询连接。缺口是把这写成<strong>显式合同</strong>：哪条 FD 不再由模式保证，改由应用、触发器或物化维护。不是「为了性能可以随便宽表」。</p><p><span class="marginnote">直觉类比：连接依赖像「三人才算数」的约定——供应商、零件、项目三个角色，任意两两关系拼起来会出现现实里不存在的组合，三张关系全连上才能还原真相。5NF 管的就是这种「必须三路一起拼」的约束。</span></p><p><span class="marginnote">常见误区：初学者容易以为「范式越高越好，反规范化是偷懒」。实际上范式拉满的代价是每次查询都要连三四张表；反规范化的关键不在冗余本身，而在有没有人（触发器、物化视图或应用逻辑）负责让冗余的两边保持一致。</span></p><p><span class="marginnote">Fagin 1979。Date 强调 5NF 与「只按键连接」的直觉。物化视图是受控反规范化：有定义查询，维护规则可分析。宽表缓存若无定义，只是副本漂移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>5NF 设计：若业务约束确实是三路可拼且两路不可，则拆成三张「键对」表。否则不要为理论而拆。反规范化：量连接代价与更新异常频率；冗余列随源列更新必须同步——触发器课的过程或后课物化刷新。</p><p>从 5NF 表再连回宽结果，是查询或视图，不是把基表重新加宽。OLAP 星型模式后课会系统性地反规范化维表；本课只给原则。</p>',12)),(n(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20JD%5B%22%E8%BF%9E%E6%8E%A5%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20F5%5B%225NF%3A%20%E7%94%B1%E9%94%AE%E8%95%B4%E5%90%AB%22%5D%0A%20%20F5%20--%3E%20SPLIT%5B%22%E5%A4%9A%E8%B7%AF%E6%8A%95%E5%BD%B1%E8%A1%A8%22%5D%0A%20%20DEN%5B%22%E5%8F%8D%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%20--%3E%20RED%5B%22%E5%8F%97%E6%8E%A7%E5%86%97%E4%BD%99%22%5D%0A%20%20RED%20--%3E%20MAINT%5B%22%E8%A7%A6%E5%8F%91%E5%99%A8%20%2F%20%E7%89%A9%E5%8C%96%20%2F%20%E5%BA%94%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"无损分解的终点：5NF 说「没有额外的无损切法」。再拆只会增加连接、不消除由 JD 造成的异常。反规范化增加更新异常风险，换的是读路径上的连接与随机 I/O——代价模型在优化器单元量化，本课只定性。",-1)),a[5]||(a[5]=E("p",null,"与 ORM：宽对象常诱使反规范化；阻抗课已警告导航不是计划。冗余字段会让 N+1 看起来「少连表」，更新却更脆。",-1)),a[6]||(a[6]=E("p",null,"第一张图回答「5NF 与反规范化各是什么」；这张图补第二个问题：为什么供应商–零件–项目这类约束两路连接不够、必须三路才无损。",-1)),(n(),l(s,null,{default:e(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%85%B3%E7%B3%BB%20R%EF%BC%9A%E4%BE%9B%E5%BA%94%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20P1%5B%22%E6%8A%95%E5%BD%B1%EF%BC%9A%E4%BE%9B%E5%BA%94%E5%95%86-%E9%9B%B6%E4%BB%B6%22%5D%0A%20%20R%20--%3E%20P2%5B%22%E6%8A%95%E5%BD%B1%EF%BC%9A%E9%9B%B6%E4%BB%B6-%E9%A1%B9%E7%9B%AE%22%5D%0A%20%20R%20--%3E%20P3%5B%22%E6%8A%95%E5%BD%B1%EF%BC%9A%E4%BE%9B%E5%BA%94%E5%95%86-%E9%A1%B9%E7%9B%AE%22%5D%0A%20%20P1%20--%3E%20TWO%5B%22%E5%8F%AA%E8%BF%9E%E4%B8%A4%E8%B7%AF%22%5D%0A%20%20P2%20--%3E%20TWO%0A%20%20TWO%20--%3E%20FAKE%5B%22%E6%8B%BC%E5%87%BA%E7%8E%B0%E5%AE%9E%E4%B8%AD%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%9A%84%E7%BB%84%E5%90%88%22%5D%0A%20%20P1%20--%3E%20THREE%5B%22%E4%B8%89%E8%B7%AF%E5%85%A8%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20P2%20--%3E%20THREE%0A%20%20P3%20--%3E%20THREE%0A%20%20THREE%20--%3E%20LOSSLESS%5B%22%E6%97%A0%E6%8D%9F%E8%BF%98%E5%8E%9F%20R%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">数字实例：订单表 100 万行，每行重复存顾客名（约 20 字节）就多占约 20 MB 存储；更大的代价在更新——顾客改名一次，就要同步改 100 万行。省下的是每次查询的一次 JOIN，换来的是改名时一次百万行的 UPDATE。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DKNF 等更强范式写入必做。也不开始 Selinger 搜索。域-键范式点名存在：约束若都能收成域与键，则理论漂亮，现实 CHECK 与触发器仍在。</p><p>后课默认：模式先按 3NF/BCNF/需要时 4NF 设计；5NF 仅当真正有多路 JD；冗余必须有维护者。优化器单元第一课：给定模式，如何搜连接顺序。</p><p>依赖理论补的是主干范式课的推导与 4NF/5NF；不是重开关系模型第一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>5NF 处理非平凡连接依赖，比 4NF 更稀。</li><li>反规范化是显式冗余加维护，不是忘了分解。</li><li>下一单元 Selinger 动态规划：在合法计划空间里搜代价。</li><li>出处：Fagin 1979；Date；Ramakrishnan and Gehrke。</li></ul>',7))])}const _=o(p,[["render",F]]);export{u as __pageData,_ as default};
